import { graphql } from 'gatsby';
import React from 'react';

import Header from '../components/header';
import Layout from '../components/layout';
import SEO from '../components/seo';

const classes = {
  card: 'mt-12 bg-white/90 rounded-lg p-6 shadow-lg md:p-10',
  title: 'text-4xl text-gray-900 font-bold',
  date: 'mt-2 text-gray-600 font-light',
  wrapper: 'mt-8 blog-content',
};

const BlogPost = ({ data }) => {
  const post = data.markdownRemark;

  return (
    <Layout>
      <Header metadata={data.site.siteMetadata} />
      <article className={classes.card}>
        <h1 className={classes.title}>{post.frontmatter.title}</h1>
        <p className={classes.date}>Posted on {post.frontmatter.date}</p>
        <div
          className={classes.wrapper}
          dangerouslySetInnerHTML={{ __html: post.html }}
        />
      </article>
    </Layout>
  );
};

export default BlogPost;

export const Head = ({ data, location }) => (
  <SEO
    title={data.markdownRemark.frontmatter.title}
    description={data.markdownRemark.frontmatter.description || data.markdownRemark.excerpt}
    pathname={location.pathname}
  />
);

export const pageQuery = graphql`
  query BlogPostBySlug($slug: String!) {
    site {
      siteMetadata {
        name
        title
        description
        about
        author
        github
        linkedin
      }
    }
    markdownRemark(fields: { slug: { eq: $slug } }) {
      id
      excerpt(pruneLength: 160)
      html
      frontmatter {
        title
        date(formatString: "MMMM DD, YYYY")
        description
      }
    }
  }
`;
